expandGroupboxesWithRequiredFields(){if(!this.mainForm)return;const requiredFields=this.mainForm.querySelectorAll('[data-required="true"]');const expandedGroups=new Set();requiredFields.forEach(field=>{const value=field.value||'';if(value!=='')return;const parentRow=field.closest('tr[id^="_g"]');if(!parentRow)return;const match=parentRow.id.match(/^_g(\d+)_/);if(!match)return;const groupId=match[1];if(expandedGroups.has(groupId))return;const groupbox=document.querySelector(`cma-groupbox[group-id="${groupId}"]`);if(groupbox&&!groupbox.isOpen){groupbox.open();expandedGroups.add(groupId)}})}
