getChangedFields(){const mainForm=this.mainForm;if(!mainForm)return[];const changes=[];const formData=new FormData(mainForm);const origValues=this.originalValues;const labelMap={};mainForm.querySelectorAll('label').forEach(label=>{const forAttr=label.getAttribute('for');const text=label.textContent.trim().replace('*','').trim();if(forAttr&&text){labelMap[forAttr.toLowerCase()]=text}});mainForm.querySelectorAll('[data-label]').forEach(field=>{const name=field.name||field.dataset.field;if(name){labelMap[name.toLowerCase()]=field.dataset.label}});const isBoolFalse=(val)=>{const s=String(val||'').toLowerCase();return s===''||s==='n'||s==='0'||s==='false'||s==='nee'||s==='null'||s==='undefined'};const isBoolTrue=(val)=>{const s=String(val||'').toLowerCase();return s==='j'||s==='y'||s==='1'||s==='-1'||s==='true'||s==='ja'||s==='yes'};for(const[name,newValue]of formData.entries()){if(name.startsWith('_')||name.endsWith('__label')||name==='ID'||name==='FormID')continue;const originalValue=origValues[name]??origValues[name.toLowerCase()]??'';const origStr=String(originalValue||'');const newStr=String(newValue||'');if(origStr===newStr)continue;const isBoolField=name.startsWith('b')||(isBoolFalse(origStr)&&isBoolFalse(newStr))||(isBoolTrue(origStr)&&isBoolTrue(newStr));if(isBoolField){if((isBoolFalse(origStr)&&isBoolFalse(newStr))||(isBoolTrue(origStr)&&isBoolTrue(newStr))){continue}}
const label=labelMap[name.toLowerCase()]||name;changes.push({field:name,label:label,oldValue:origStr,newValue:newStr})}
mainForm.querySelectorAll('input[type="checkbox"], lib-switch').forEach(field=>{const name=field.name;if(!name||name.startsWith('_'))return;const isChecked=field.checked;const originalValue=origValues[name]??origValues[name.toLowerCase()];const wasChecked=originalValue===!0||originalValue==='true'||originalValue==='1'||originalValue==='True'||originalValue===-1;if(isChecked!==wasChecked){const label=labelMap[name.toLowerCase()]||name;changes.push({field:name,label:label,oldValue:wasChecked?'Ja':'Nee',newValue:isChecked?'Ja':'Nee'})}});return changes}
captureOriginalValues(){const mainForm=this.mainForm;if(!mainForm)return;mainForm.querySelectorAll('[data-original-value]').forEach(field=>{delete field.dataset.originalValue});const formData=new FormData(mainForm);let capturedCount=0;const processedFields=new Set();for(const[name,value]of formData.entries()){if(name.startsWith('_'))continue;if(name.endsWith('__label'))continue;if(name.endsWith('[]'))continue;const field=mainForm.querySelector(`[name="${name}"]`);if(field){field.dataset.originalValue=value??'';processedFields.add(name);capturedCount++}}
mainForm.querySelectorAll('input[type="text"], input[type="hidden"], textarea, select').forEach(field=>{const name=field.name;if(!name||processedFields.has(name))return;if(name.startsWith('_')||name.endsWith('__label')||name.endsWith('[]'))return;field.dataset.originalValue=field.value??'';processedFields.add(name);capturedCount++});mainForm.querySelectorAll('input[type="checkbox"], lib-switch').forEach(field=>{const name=field.name;if(name&&!name.startsWith('_')){field.dataset.originalValue=field.checked?'true':'false';capturedCount++}})}
formatChangeSummary(maxItems=5,maxValueLength=50){const changes=this.getChangedFields();if(changes.length===0)return'';const truncate=(str,len)=>{if(!str||str.length<=len)return str;return str.substring(0,len)+'...'};let html='<details style="margin-top:12px;font-size:var(--font-size-sm);text-align:left;">';const countLabel=changes.length===1?'1 wijziging':changes.length+' wijzigingen';html+='<summary style="cursor:pointer;color:var(--color-primary, #204496);font-weight:500;user-select:none;">Toon '+countLabel+'</summary>';html+='<table style="border-collapse:collapse;width:100%;font-size:var(--font-size-xs);margin-top:8px;">';html+='<thead><tr style="background:var(--bg-surface-alt, #f5f5f5);border-bottom:1px solid var(--border-color, #ddd);">';html+='<th style="padding:4px 8px;text-align:left;font-weight:500;">Veld</th>';html+='<th style="padding:4px 8px;text-align:left;font-weight:500;">Was</th>';html+='<th style="padding:4px 8px;text-align:left;font-weight:500;">Wordt</th>';html+='</tr></thead><tbody>';const showCount=Math.min(changes.length,maxItems);for(let i=0;i<showCount;i++){const change=changes[i];const isLongValue=change.newValue.length>maxValueLength||change.oldValue.length>maxValueLength;const oldDisplay=isLongValue?'<span class="cma-js__em">(gewijzigd)</span>':(change.oldValue||'<span class="cma-js__em">leeg</span>');const newDisplay=isLongValue?'<span class="cma-js__em">(gewijzigd)</span>':(change.newValue||'<span class="cma-js__em">leeg</span>');html+=`<tr style="border-bottom:1px solid var(--border-color-light, #eee);">`;html+=`<td style="padding:4px 8px;font-weight:500;">${change.label}</td>`;html+=`<td style="padding:4px 8px;color:var(--color-danger, #c00);">${truncate(oldDisplay, maxValueLength)}</td>`;html+=`<td style="padding:4px 8px;color:var(--color-success, #060);">${truncate(newDisplay, maxValueLength)}</td>`;html+=`</tr>`}
html+='</tbody></table>';if(changes.length>maxItems){html+=`<div style="margin-top:6px;font-style:italic;color:var(--text-muted, #666);">... en ${changes.length - maxItems} meer ...</div>`}
html+='</details>';return html}
